<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';
apiRequirePlatformAdministrator();
apiRequirePermission('admin.reports', 'admin.audit', 'progop.manage_all');
if ($_SERVER['REQUEST_METHOD'] !== 'GET') apiError('Metoda nu este acceptata.', 405);
$period=(string)($_GET['period']??'daily');$reference=(string)($_GET['date']??date('Y-m-d'));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$reference))apiError('Data trebuie sa fie AAAA-LL-ZZ.');$point=new DateTimeImmutable($reference);
[$start,$end]=match($period){'daily'=>[$point->format('Y-m-d'),$point->format('Y-m-d')],'monthly'=>[$point->modify('first day of this month')->format('Y-m-d'),$point->modify('last day of this month')->format('Y-m-d')],'annual'=>[$point->format('Y-01-01'),$point->format('Y-12-31')],default=>apiError('Perioada acceptata: daily, monthly sau annual.')};
$operations=$db->prepare('SELECT o.*,r.name room_name,ot.name operation_type,p.display_name doctor_name,u.username created_by_username FROM operations o JOIN operation_rooms r ON r.id=o.room_id LEFT JOIN operation_types ot ON ot.id=o.operation_type_id JOIN people p ON p.id=o.scheduled_doctor_id JOIN users u ON u.id=o.created_by WHERE o.scheduled_date BETWEEN :a AND :b ORDER BY o.scheduled_date,r.display_order,o.display_order,o.id');$operations->execute(['a'=>$start,'b'=>$end]);
$guards=$db->prepare('SELECT ga.*,p.display_name current_person_name,po.display_name original_person_name,gv.status version_status FROM guard_assignments ga JOIN guard_plan_versions gv ON gv.id=ga.version_id JOIN guard_plans gp ON gp.current_version_id=gv.id JOIN people p ON p.id=ga.current_person_id LEFT JOIN people po ON po.id=ga.original_person_id WHERE ga.guard_date BETWEEN :a AND :b ORDER BY ga.guard_date,ga.specialty,ga.line_no');$guards->execute(['a'=>$start,'b'=>$end]);
$logs=$db->prepare('SELECT al.*,u.username,p.display_name user_name FROM audit_logs al LEFT JOIN users u ON u.id=al.user_id LEFT JOIN people p ON p.id=u.person_id WHERE al.created_at>=:a AND al.created_at<:b ORDER BY al.created_at,al.id');$logs->execute(['a'=>$start.' 00:00:00','b'=>(new DateTimeImmutable($end))->modify('+1 day')->format('Y-m-d 00:00:00')]);
$atiPath=dirname(__DIR__,2).'/storage/config/ati_room_assignments.json';$atiRaw=is_file($atiPath)?json_decode((string)file_get_contents($atiPath),true):[];$atiAssignments=[];foreach(($atiRaw['assignments']??[])as$date=>$assignment){if($date>=$start&&$date<=$end)$atiAssignments[$date]=$assignment;}
$guardLinesPath=dirname(__DIR__,2).'/storage/config/guard_monthly_lines.json';$guardMonthlyLines=is_file($guardLinesPath)?json_decode((string)file_get_contents($guardLinesPath),true):[];
$operationRows=$operations->fetchAll();$operationIds=array_fill_keys(array_map(static fn(array$row):string=>(string)$row['id'],$operationRows),true);
$dashboardPath=dirname(__DIR__,2).'/storage/config/dashboard_operation_state.json';$dashboardRaw=is_file($dashboardPath)?json_decode((string)file_get_contents($dashboardPath),true):[];$dashboardStates=[];foreach(($dashboardRaw['operations']??[])as$id=>$state){if(isset($operationIds[(string)$id]))$dashboardStates[(string)$id]=$state;}
$filename=sprintf('intern_backup_%s_%s_%s.json',$period,str_replace('-','',$start),str_replace('-','',$end));$payload=['format'=>'intern-operational-backup','format_version'=>4,'generated_at'=>date(DATE_ATOM),'period'=>$period,'start_date'=>$start,'end_date'=>$end,'operations'=>$operationRows,'operation_dashboard_states'=>$dashboardStates,'guards'=>$guards->fetchAll(),'ati_room_assignments'=>$atiAssignments,'guard_monthly_lines'=>$guardMonthlyLines,'audit_logs'=>$logs->fetchAll()];
apiAudit($db,'backup.exported','backup',null,null,['period'=>$period,'start_date'=>$start,'end_date'=>$end,'filename'=>$filename]);header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'"');echo json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);
